 r=dict(id=f'physics-chapter-31-{kind}-{n}',parts=parts,reasoning=why+' Verification: '+why,sourcePages=pages or[page],assumptions=assumptions or['Ideal components and negligible wire resistance unless an explicit resistance is included; sinusoidal driven circuits are in steady state.'])
 if scope:r['scope']=scope
 if notice:r['reviewNotice']=notice
 if reference:r['referenceAnswer']=reference
 rows.append(r)
