def prose_clean(s):
 return re.sub(r"[A-Za-z]{8,}",lambda m:PROSE_FIXES.get(m.group(0),m.group(0)),s)
for r in rows:
 for key in ["reasoning","scope","reviewNotice","referenceAnswer"]:
  if key in r:r[key]=prose_clean(r[key])
 r["assumptions"]=[prose_clean(v) for v in r["assumptions"]]
 for f in r["parts"]:
  for key in ["label","explanation"]:f[key]=prose_clean(f[key])
  if f["type"]=="choice":
   f["answer"]=prose_clean(f["answer"]);f["options"]=[prose_clean(v) for v in f["options"]]

